from collections import Counter


def transform(grid):
    cells = [
        (r + c, value)
        for r, row in enumerate(grid)
        if r >= 3
        for c, value in enumerate(row)
        if c >= 3 and value != 0
    ]
    best = None
    for period in range(2, 13):
        buckets = [Counter() for _ in range(period)]
        for diagonal, value in cells:
            buckets[diagonal % period][value] += 1
        mapping = [bucket.most_common(1)[0][0] if bucket else None for bucket in buckets]
        score = sum(bucket[mapping[i]] for i, bucket in enumerate(buckets) if mapping[i] is not None)
        candidate = (score, -period, mapping)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    mapping = best[2]
    out = [row[:] for row in grid]
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 1 if c < 2 else 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                out[r][c] = mapping[(r + c) % len(mapping)]
    return out
